/**
 * The tier table generator. `src/generated/table.js` is emitted from
 * `src/table-source.json` and is never hand-edited: the test regenerates it
 * and compares bytes, so a table that drifted from its source fails the gate.
 *
 *   node scripts/generate-table.mjs
 */

import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

const ROOT = new URL('../', import.meta.url);

/** The exact bytes `src/generated/table.js` holds for a given source. */
export function renderTable(source) {
  const lines = [
    '// Generated by scripts/generate-table.mjs from src/table-source.json. Do not edit.',
    '',
    'export const TIERS = Object.freeze([',
  ];
  for (const tier of source.tiers) lines.push(`  Object.freeze({ id: ${JSON.stringify(tier.id)}, floor: ${tier.floor} }),`);
  lines.push(']);', '', '/** The first tier whose floor the score reaches. */', 'export function tierOf(score) {',
    '  for (const tier of TIERS) if (score >= tier.floor) return tier.id;', "  return 'plain';", '}', '');
  return lines.join('\n');
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const source = JSON.parse(await readFile(new URL('src/table-source.json', ROOT), 'utf8'));
  await writeFile(new URL('src/generated/table.js', ROOT), renderTable(source));
}
